From aa49302bb10b63983651a40b98f7f1bc16ccdd68 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 08:55:59 +0100
Subject: [PATCH] libtaskmanager: show transients of windows that skip the
 taskbar

Some Wine apps make their main window transient for a tiny hidden owner
window that skips the taskbar, so the main window had no task entry at
all. Such transients are now shown and highlighted in their own place.

BUG: 514758
---
 libtaskmanager/waylandtasksmodel.cpp | 35 +++++++++++++++++++---------
 1 file changed, 24 insertions(+), 11 deletions(-)

diff --git a/libtaskmanager/waylandtasksmodel.cpp b/libtaskmanager/waylandtasksmodel.cpp
index ed0b90cbbf..97f2ce4b03 100644
--- a/libtaskmanager/waylandtasksmodel.cpp
+++ b/libtaskmanager/waylandtasksmodel.cpp
@@ -460,6 +460,7 @@ public:
     void initWayland();
     auto findWindow(PlasmaWindow *window) const;
     void addWindow(PlasmaWindow *window);
+    PlasmaWindow *effectiveWindow(PlasmaWindow *window) const;

     const AppData &appData(PlasmaWindow *window);

@@ -549,6 +550,21 @@ auto WaylandTasksModel::Private::findWindow(PlasmaWindow *window) const
     });
 }

+// The window that represents a transient in the task list is its topmost leader that is not
+// skip-taskbar. If every leader is skip-taskbar, the transient represents itself.
+PlasmaWindow *WaylandTasksModel::Private::effectiveWindow(PlasmaWindow *window) const
+{
+    PlasmaWindow *effective = window;
+
+    for (PlasmaWindow *leader = window->parentWindow; leader; leader = leader->parentWindow) {
+        if (!leader->windowState.testFlag(PlasmaWindow::state::state_skiptaskbar)) {
+            effective = leader;
+        }
+    }
+
+    return effective;
+}
+
 void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
 {
     if (findWindow(window) != windows.end()) {
@@ -617,11 +633,7 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
     });

     if (window->windowState & PlasmaWindow::state::state_active) {
-        PlasmaWindow *effectiveActive = window;
-        while (effectiveActive->parentWindow) {
-            effectiveActive = effectiveActive->parentWindow;
-        }
-
+        PlasmaWindow *effectiveActive = effectiveWindow(window);
         lastActivated[effectiveActive] = QDateTime::currentDateTime();
         activeWindow = effectiveActive;
     }
@@ -629,11 +641,7 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
     QObject::connect(window, &PlasmaWindow::activeChanged, q, [window, this] {
         const bool active = window->windowState & PlasmaWindow::state::state_active;

-        PlasmaWindow *effectiveWindow = window;
-
-        while (effectiveWindow->parentWindow) {
-            effectiveWindow = effectiveWindow->parentWindow;
-        }
+        PlasmaWindow *effectiveWindow = this->effectiveWindow(window);

         if (active) {
             lastActivated[effectiveWindow] = QDateTime::currentDateTime();
@@ -668,6 +676,7 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)
         if (transients.remove(window)) {
             if (leader) { // leader change.
                 transients.insert(window, leader);
+                dataChanged(window, SkipTaskbar);
             } else { // lost a leader, add to regular windows list.
                 dataChanged(window, SkipTaskbar);
             }
@@ -782,6 +791,10 @@ void WaylandTasksModel::Private::addWindow(PlasmaWindow *window)

     QObject::connect(window, &PlasmaWindow::skipTaskbarChanged, q, [window, this] {
         this->dataChanged(window, SkipTaskbar);
+
+        for (PlasmaWindow *transient : transients.keys(window)) {
+            this->dataChanged(transient, SkipTaskbar);
+        }
     });

     QObject::connect(window, &PlasmaWindow::applicationMenuChanged, q, [window, this] {
@@ -967,7 +980,7 @@ QVariant WaylandTasksModel::data(const QModelIndex &index, int role) const
     case IsDemandingAttention:
         return window->windowState.testFlag(PlasmaWindow::state::state_demands_attention) || d->transientsDemandingAttention.contains(window);
     case SkipTaskbar:
-        return window->windowState.testFlag(PlasmaWindow::state::state_skiptaskbar) || d->transients.contains(window);
+        return window->windowState.testFlag(PlasmaWindow::state::state_skiptaskbar) || d->effectiveWindow(window) != window;
     case SkipPager:
         return false;
     case AppPid:
